-- IFSI validated external sources batch 2
-- Respiratory system, Skin, ABO blood groups
-- Sources: MedlinePlus, NHS Blood and Transplant

update public.curriculum_lessons
set content='L’air entre par le nez ou la bouche, traverse le pharynx, le larynx et la trachée, puis gagne les bronches, les bronchioles et enfin les alvéoles. Les alvéoles sont le siège principal des échanges gazeux avec les capillaires pulmonaires : l’oxygène diffuse vers le sang tandis que le dioxyde de carbone diffuse du sang vers les alvéoles avant d’être expiré. Lors de l’inspiration, le diaphragme se contracte et s’abaisse, le volume thoracique augmente et la pression diminue, ce qui fait entrer l’air. Lors de l’expiration calme, le diaphragme se relâche et le volume thoracique diminue.',
source_files=coalesce(source_files,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('label','MedlinePlus — Gas exchange','url','https://medlineplus.gov/ency/anatomyvideos/000059.htm','validation','institutional_validated'),jsonb_build_object('label','MedlinePlus — Breathing','url','https://medlineplus.gov/ency/anatomyvideos/000018.htm','validation','institutional_validated'),jsonb_build_object('label','MedlinePlus — Lung anatomy','url','https://medlineplus.gov/ency/imagepages/17100.htm','validation','institutional_validated')),updated_at=now()
where id='45bc76b1-4ba0-417e-934f-05d9c7c28201'::uuid;

update public.curriculum_lessons
set content='La peau est le plus grand organe du corps et participe notamment à la protection contre l’environnement, à la sensibilité et à la thermorégulation. Elle comprend trois grandes couches : l’épiderme en surface, le derme en profondeur intermédiaire et l’hypoderme en dessous. L’épiderme contient notamment des cellules produisant de la kératine et de la mélanine. Le derme contient des vaisseaux sanguins, des récepteurs sensoriels, des follicules pileux et des glandes. L’hypoderme contient notamment du tissu adipeux qui contribue à l’isolation thermique. La vasoconstriction cutanée participe à la conservation de chaleur lorsqu’il fait froid.',
source_files=coalesce(source_files,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('label','MedlinePlus — Components of skin','url','https://medlineplus.gov/ency/anatomyvideos/000029.htm','validation','institutional_validated'),jsonb_build_object('label','MedlinePlus — Skin layers','url','https://medlineplus.gov/ency/imagepages/8912.htm','validation','institutional_validated')),updated_at=now()
where id='e8eacf16-2ca7-495a-acf2-aa0b6a1502f8'::uuid;

update public.curriculum_lessons
set content='Le système ABO classe le sang en groupes A, B, AB et O selon les antigènes présents à la surface des globules rouges. Le groupe O ne porte ni antigène A ni antigène B, tandis que le groupe AB porte les deux. La compatibilité transfusionnelle dépend de la correspondance entre les antigènes des globules rouges du donneur et les anticorps du receveur. Le groupe sanguin est hérité. Avant une transfusion, le laboratoire vérifie les groupes sanguins du patient et du donneur afin de réduire le risque d’incompatibilité. Pour les globules rouges, un patient AB+ peut recevoir des globules rouges de tous les groupes ABO/RhD de base, alors qu’un patient A- reçoit habituellement des globules rouges A- ou O-.',
source_files=coalesce(source_files,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('label','NHS Blood and Transplant — Blood matching and antibodies','url','https://www.nhsbt.nhs.uk/what-we-do/clinical-and-research/blood-group-genotyping/hospital-and-lab-staff/frequently-asked-questions/','validation','institutional_validated'),jsonb_build_object('label','NHS Blood and Transplant — ABO groups and haemovigilance','url','https://www.nhsbt.nhs.uk/research-and-development/research-blogs/haemovigilance-qa-with-paula-bolton-maggs/','validation','institutional_validated')),updated_at=now()
where id='482b61ad-d525-48e1-970d-f40f33e0a96d'::uuid;

on conflict(id) do nothing;

